source("analisis_bayesiano/00_funciones_bayes.R")
td<-"resultados/corrida_2026-08-10/tablas"
frec<-bind_rows(read_csv(file.path(td,"TABLA_3_MODELO_A_SOCIAL_ATENCION.csv"),show_col_types=FALSE),read_csv(file.path(td,"TABLA_4_MODELO_B_MATERNO_CLINICO.csv"),show_col_types=FALSE),read_csv(file.path(td,"TABLA_5_MODELO_C_OBSTETRICO.csv"),show_col_types=FALSE))%>%distinct(Variable,.keep_all=TRUE)
bay<-bind_rows(read_csv(file.path(DIR_TABLAS,"TABLA_BAYES_PRINCIPAL.csv"),show_col_types=FALSE),read_csv(file.path(DIR_TABLAS,"TABLA_BAYES_CLINICO_INGRESO.csv"),show_col_types=FALSE),read_csv(file.path(DIR_TABLAS,"TABLA_BAYES_OBSTETRICO.csv"),show_col_types=FALSE))
spec<-tribble(~Factor,~bp,~fp,"DPP","DPP","Desprendimiento","Eclampsia","Eclampsia","Eclampsia","Riesgo alto","Riesgo alto","Riesgo alto","Riesgo inminente","Riesgo inminente","Riesgo inminente","Acompañada","Acompañada","Acompanada","Controles prenatales","Controles prenatales","Controles","Sesiones psicoprofilaxis","Sesiones de psicoprofilaxis","Sesiones","RPM","RPM","RPM")
out<-bind_rows(lapply(seq_len(nrow(spec)),function(i){b<-bay[grepl(spec$bp[i],bay$Variable,ignore.case=TRUE),]%>%slice(1);f<-frec[grepl(spec$fp[i],frec$Variable,ignore.case=TRUE),]%>%slice(1);if(!nrow(b))return(NULL);tibble(Factor=spec$Factor[i],Modelo=b$Modelo,OR_frecuentista=if(nrow(f))as.numeric(f$aOR) else NA_real_,IC95_frecuentista=if(nrow(f))f$IC95 else NA_character_,p_frecuentista=if(nrow(f))as.numeric(f$p) else NA_real_,OR_bayesiano=b$OR_posterior,CrI95_bayesiano=sprintf("%.2f-%.2f",b$CrI95_inf,b$CrI95_sup),P_OR_mayor_1=b$P_OR_mayor_1,P_OR_menor_1=b$P_OR_menor_1,Direccion_coincidente=ifelse(is.na(as.numeric(f$aOR)),NA,(as.numeric(f$aOR)-1)*(b$OR_posterior-1)>=0))}))
write_csv(out,file.path(DIR_TABLAS,"TABLA_COMPARACION_FRECUENTISTA_BAYES.csv"))
p<-ggplot(out,aes(y=reorder(Factor,OR_bayesiano)))+geom_vline(xintercept=1,lty=2)+geom_point(aes(x=OR_bayesiano,color="Bayesiano"),size=2)+geom_point(aes(x=OR_frecuentista,color="Frecuentista"),shape=17,size=2)+scale_x_log10()+labs(x="Odds ratio (escala log)",y=NULL,color=NULL)+theme_bw();ggsave(file.path(DIR_FIGURAS,"FOREST_COMPARACION_FREC_BAYES.png"),p,width=8,height=6,dpi=300)
